insert into edu_library_topic (
    title, summary, cover_url, bundle_price, download_count, order_num, bundle_document_id, status, del_flag,
    create_by, create_time, remark
) values (
    #{title}, #{summary}, #{coverUrl}, #{bundlePrice}, coalesce(#{downloadCount}, 0), #{orderNum}, #{bundleDocumentId}, #{status}, '0',
    #{createBy}, CURRENT_TIMESTAMP, #{remark}
)

