update edu_library_topic set del_flag = '1', update_time = CURRENT_TIMESTAMP
where topic_id in

    #{topicId}

mapper.select:
select d.document_id, d.title, d.summary, d.file_name, d.file_ext, d.file_size, d.file_url, d.cover_url, d.category_id, c.category_name, s.subject_name, d.download_price, d.download_count, d.view_count, d.allow_download, d.create_time from edu_library_topic_document td inner join edu_library_document d on d.document_id = td.document_id and d.del_flag = '0' left join edu_library_category c on c.category_id = d.category_id left join edu_subject s on s.subject_id = d.subject_id where td.topic_id = #{topicId}
and d.status = '0' and d.audit_status = '1'
order by td.order_num, td.id
